import networkx as nx

G = nx.heawood_graph()
print("Vertices:", G.number_of_nodes())
print("Edges:", G.number_of_edges())
try:
    cycles = nx.cycle_basis(G)
    min_cycle = min(len(c) for c in cycles)
    print("Girth (cycle basis min):", min_cycle)
except:
    pass

# To be absolutely sure about girth, let's compute it properly
def get_girth(graph):
    girth = float('inf')
    for n in graph.nodes():
        # BFS to find shortest cycle
        queue = [(n, [n])]
        visited = {n: 0}
        while queue:
            curr, path = queue.pop(0)
            for neighbor in graph.neighbors(curr):
                if neighbor == path[-1]:
                    continue
                if len(path) > 1 and neighbor == path[-2]:
                    continue
                if neighbor in visited:
                    girth = min(girth, len(path) + visited[neighbor])
                else:
                    visited[neighbor] = len(path)
                    queue.append((neighbor, path + [neighbor]))
    return girth

print("Girth:", get_girth(G))
print("Bipartite:", nx.is_bipartite(G))

